Sure, I'd be happy to help you with that! Here's a Python program that allows the user to add and remove tasks from a to-do list using a list data structure. This program also keeps track of the current to-do list and displays it at the end of each user input.

```python
# Initialize the to-do list as an empty list
to_do_list = []

def add_task():
    """Add a task to the to-do list."""
    global to_do_list
    task = input("Enter a task to add (or type 'done' to complete the current task): ").strip()
    if task.lower() == "done":
        # Remove the last task in the to-do list if it's not empty
        if to_do_list:
            to_do_list.pop()
        return
    to_do_list.append(task)

def remove_task():
    """Remove a task from the to-do list based on the user input."""
    global to_do_list
    task_to_remove = input("Enter the task to remove (case-sensitive): ").strip()
    if task_to_remove.lower() in to_do_list:
        to_do_list.remove(task_to_remove.lower())
    else:
        print(f"Task '{task_to_remove}' not found in the to-do list.")

def display_to_do_list():
    """Display the current to-do list."""
    global to_do_list
    print("To-Do List:")
    for task in to_do_list:
        print(f"- {task}")

if __name__ == "__main__":
    while True:
        command = input("Enter a command (add, remove, or display): ").strip().lower()
        if command == "add":
            add_task()
        elif command == "remove":
            remove_task()
        elif command == "display":
            display_to_do_list()
        elif command == "quit":
            break
        else:
            print("Invalid command. Please try again.")
```

This program allows the user to add tasks using the `add` command, remove tasks using the `remove` command, and display the current to-do list using the `display` command. The `quit` command exits the program.
